var xx = new Intl.NumberFormat('pt-BR', {
    style: 'currency',
    currency: 'BRL',
    minimumFractionDigits: 0,
    maximumFractionDigits: 0
});

function inputRange(c,t) {
    const range = document.getElementById(c),
    tooltip = document.getElementById(t);

    if (range !== null && tooltip !== null) {
        const setValue = () => {
            const newValue = Number(
                ((range.value - range.min) * 100) / (range.max - range.min)
            ),
            newPosition = 16 - newValue * 0.32;
            let valor = xx.format(range.value);
            tooltip.innerHTML = `<span>${valor}</span>`;
            document.documentElement.style.setProperty(
                "--range-progress-"+c,
                `calc(${newValue}% + (${newPosition}px))`
            );
        };

        document.addEventListener("DOMContentLoaded", setValue);
        range.addEventListener("input", setValue);
    }
}

inputRange('xcas-M','range-m');
inputRange('xcas-R','range-r');
inputRange('xcas-L','range-l');

(function ($) {
    $(document).on("mouseover", ".lknx", function() {
        $(".lknx").removeClass('hover');
        $(this).addClass('hover');
    }).on("mouseout", ".lknx", function() {
        $(".lknx").removeClass('hover');
    });

    $('.c-tabs li:first-child').addClass('active');
    $('.c-tabs-l:first').show();

    $(document).on("click", ".c-tabs li", function() {
        $('body').removeClass();
        $('.c-tabs li').removeClass('active');
        $('.c-tabs-l').hide();

        $(this).addClass('active');
        let tab_active = $(this).data('tab');
        $('#'+tab_active).show();
        $('body').addClass(tab_active);

        $('.a-bloc-hero .u-m-0 img').attr('data-loader','notload');
        if (tab_active === 'loan-tab') {
            $('.a-bloc-hero .u-m-0:nth-child(2) img').attr('data-loader','creditcard');
        } else if (tab_active === 'acount-tab') {
            $('.a-bloc-hero .u-m-0:nth-child(3) img').attr('data-loader','creditcard');
        } else {
            $('.a-bloc-hero .u-m-0:nth-child(1) img').attr('data-loader','creditcard');
        }
    });

    $('.accordion-item').on('click', function(event){
        event.preventDefault();
        // Verifica se a div clicada já está aberta
        var isOpen = $(this).hasClass('is-active');

        // Fecha todos os itens
        $('.accordion-item').removeClass('is-active');
        $('.accordion-content').slideUp();

        // Se a div clicada não estava aberta, abre
        if (!isOpen) {
            $(this).addClass('is-active');
            $(this).find('.accordion-content').slideDown();
        }
    });

    // Toggle dropdown open/close when dropdown button is clicked
    $("body").delegate(".dropdown-btn", "click", function(e){
        e.stopPropagation();

        const dropdown_container = $(this).data('id');
        const position_btn = $(this).position();
        const widthBtn = $(this).width();
        const widthEg = $(this).height();

        $(this).toggleClass("show-dropdown");
        $(dropdown_container).toggleClass("show-dropdown");
        $(dropdown_container).css({
            'position' : 'absolute',
            'top' : position_btn.top + ($(this).innerHeight() - 8),
            'left' : position_btn.left 
        });
    });

    const dropdownMenu = document.querySelector('.dropdown');

    // Close dropdown when dom element is clicked
    document.documentElement.addEventListener("click", function (e) {
        if (dropdownMenu != null) {
            if (!dropdownMenu.contains(e.target)) {
                $('.dropdown').removeClass("show-dropdown");
                $('.dropdown-btn').removeClass("show-dropdown");
            }
        }
    });
})(jQuery);